insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000072-0000-4000-8000-000000009804','00000042-0000-4000-8000-000000009800','Elimine cada distrator','A alternativa $1/(5x^{1/5})$ não corresponde à conclusão obtida ao aplicar o critério: A derivada descreve taxa instantânea; selecione a regra que corresponde a cada termo. A alternativa $1/(5x^5)$ não corresponde à conclusão obtida ao aplicar o critério: A derivada descreve taxa instantânea; selecione a regra que corresponde a cada termo. A alternativa $x^{-4/5}$ não corresponde à conclusão obtida ao aplicar o critério: A derivada descreve taxa instantânea; selecione a regra que corresponde a cada termo. Portanto, a única opção compatível é “$1/(5x^{4/5})$”.',4) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
